/* LD_PRELOAD shim: lie about the system CPU count so that libraries which
 * size their thread pools by hardware_concurrency() (Ray's raylet, boost::asio,
 * libstdc++ std::thread, polars, rayon, ...) think we only have FAKE_CPUS
 * cores. Override the actual call to FAKE_CPUS via env FAKECPUS_N.
 *
 * Build: gcc -O2 -shared -fPIC -o fakecpus.so fakecpus.c -ldl
 * Use:   LD_PRELOAD=/path/to/fakecpus.so FAKECPUS_N=8  ./your_program
 */
#define _GNU_SOURCE
#include <unistd.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <dlfcn.h>
#include <sys/sysinfo.h>

static long fake_n(void) {
    const char *e = getenv("FAKECPUS_N");
    if (e && *e) {
        long v = strtol(e, NULL, 10);
        if (v > 0) return v;
    }
    return 8;
}

long sysconf(int name) {
    static long (*real)(int) = NULL;
    if (!real) real = dlsym(RTLD_NEXT, "sysconf");
    if (name == _SC_NPROCESSORS_ONLN || name == _SC_NPROCESSORS_CONF) {
        return fake_n();
    }
    return real(name);
}

int get_nprocs(void) {
    return (int)fake_n();
}

int get_nprocs_conf(void) {
    return (int)fake_n();
}

